// crates/domain/change/src/services/derive_state.rs の末尾（単体テスト）
#[cfg(test)]
mod tests {
    use super::*;

    // 決定表の1列に1つのテスト。入力はすべて値で渡す（時刻 ・ id ・ 乱数を関数の中で作らない）
    #[test]
    fn unverified_rule_makes_instance_wait_for_human() {
        let results = vec![verdict("r1", Verdict::Verified), verdict("r2", Verdict::Unverified)];
        assert_eq!(derive_state(&results, &[]), InstanceState::AwaitingJudgment);
    }

    // Creation Method：このテストに効かない欄は既定の値で埋め、読む人に見せない
    fn verdict(rule: &str, value: Verdict) -> RuleResult { RuleResult::machine(rule, value) }
}

