// crates/application/tests/record_change.rs
mod common;
#[test]
fn record_change_reports_unreachable_and_writes_nothing() {
    let records = common::InMemoryChangeRecords::default();
    let out = record_change(&common::UnreachableChanges, &records, input(FIXED_NOW, FIXED_ID));
    assert!(out.is_unreachable(), "届かないを 0件として返した");
    assert!(records.written.borrow().is_empty(), "届かないのに記録を書いた");
}

